const rowVariants = {
  hidden: {
    x: typeof window === "undefined" ? 0 : window.outerWidth + 5,
  },
  visible: {
    x: 0,
  },
  exit: {
    x: typeof window === "undefined" ? 0 : -window.outerWidth - 5,
  },
};

const boxVariants: Variants = {
  normal: {
    scale: 1,
    y: 0,
  },
  hover: {
    scale: 1.3,
    y: -50,
    transition: {
      delay: 0.3,
      duration: 0.3,
      type: "tween",
      ease: "easeOut",
    },
  },
};

const infoVariants: Variants = {
  hover: {
    opacity: 1,
    transition: {
      duration: 0.15,
      type: "tween",
    },
  },
};

const offset = 6;

interface MovieSliderProps {
  title: string;
  sliderId: string;
  data?: IGetMoviesResult;
  hideFirstMovie?: boolean;
  overlapBanner?: boolean;
  onBoxClick: MovieClickHandler;
  registerNext?: (handler: (() => void) | null) => void;
  activeLayoutId?: string | null;
}

function MovieSlider({
  title,
  sliderId,
  data,
  hideFirstMovie,
  overlapBanner,
  onBoxClick,
  registerNext,
  activeLayoutId,
}: MovieSliderProps) {
  const [index, setIndex] = useState(0);
  const [leaving, setLeaving] = useState(false);

  const sliceStart = hideFirstMovie ? 1 : 0;
  const movies = data?.results ?? [];
  const moviesToShow = movies.slice(sliceStart);
  const totalMovies = moviesToShow.length;
  const pageCount = Math.ceil(totalMovies / offset);
  const hasMultiplePages = pageCount > 1;

  useEffect(() => {
    setIndex(0);
    setLeaving(false);
  }, [totalMovies]);

  const toggleLeaving = useCallback(() => setLeaving((prev) => !prev), []);

  const handleNext = useCallback(() => {
    if (leaving) return;
    if (!totalMovies) return;
    const maxIndex = Math.max(pageCount - 1, 0);
    const nextIndex = index === maxIndex ? 0 : index + 1;
    if (nextIndex === index) return;
    toggleLeaving();
    setIndex(nextIndex);
  }, [index, leaving, pageCount, toggleLeaving, totalMovies]);

  useEffect(() => {
    registerNext?.(totalMovies ? handleNext : null);
    return () => registerNext?.(null);
  }, [registerNext, handleNext, totalMovies]);

  if (!totalMovies) {
    return null;
  }

  const chunkStart = offset * index;
  const moviesOnPage = moviesToShow.slice(chunkStart, chunkStart + offset);

  return (
    <SliderSection $overlap={overlapBanner}>
      <SliderHeader $overlap={overlapBanner}>
        <SliderTitle>{title}</SliderTitle>
        {hasMultiplePages ? (
          <ControlButton
            type="button"
            onClick={handleNext}
            disabled={leaving}
            aria-label={`Show more ${title.toLowerCase()}`}
          >
            Next
            <span aria-hidden="true">›</span>
          </ControlButton>
        ) : null}
      </SliderHeader>
      <SliderViewport $overlap={overlapBanner}>
        <AnimatePresence initial={false} onExitComplete={toggleLeaving}>
          <Row
            key={`${sliderId}-${index}`}
            variants={rowVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            transition={{ type: "tween", duration: 1 }}
          >
            {moviesOnPage.map((movie) => {
              const layoutId = `${sliderId}-${movie.id}`;
              const backgroundImage = makeImagePath(
                movie.backdrop_path || movie.poster_path || "",
                "w500"
              );
              return (
                <Box
                  layoutId={layoutId}
                  key={layoutId}
                  whileHover="hover"
                  initial="normal"
                  variants={boxVariants}
                  onClick={() => onBoxClick(movie, layoutId)}
                  transition={{ type: "tween" }}
                  bgphoto={backgroundImage}
                  $isActive={layoutId === activeLayoutId}
                >
                  <Info variants={infoVariants}>
                    <h4>{movie.title}</h4>
                  </Info>
                </Box>
              );
            })}
          </Row>
        </AnimatePresence>
      </SliderViewport>
    </SliderSection>
  );
}

function Home() {
  const navigate = useNavigate();
  const bigMovieMatch = useMatch("/movies/:movieId");
  const { scrollY } = useScroll();
  const { data: nowPlayingData, isLoading: nowPlayingLoading } =
    useQuery<IGetMoviesResult>({
      queryKey: ["movies", "nowPlaying"],
      queryFn: getMovies,
    });
  const { data: topRatedData } = useQuery<IGetMoviesResult>({
    queryKey: ["movies", "topRated"],
    queryFn: getTopRatedMovies,
  });
  const { data: upcomingData } = useQuery<IGetMoviesResult>({
    queryKey: ["movies", "upcoming"],
    queryFn: getUpcomingMovies,
  });

  const [activeLayoutId, setActiveLayoutId] = useState<string | null>(null);

  const nowPlayingNextRef = useRef<(() => void) | null>(null);
  const registerNowPlayingNext = useCallback((handler: (() => void) | null) => {
    nowPlayingNextRef.current = handler;
  }, []);

  const onBannerClick = useCallback(() => {
    nowPlayingNextRef.current?.();
  }, []);

  const onBoxClicked = useCallback<MovieClickHandler>(
    (movie, layoutId) => {
      setActiveLayoutId(layoutId);
      navigate(`/movies/${movie.id}`);
    },
    [navigate]
  );

  const onOverlayClick = useCallback(() => {
    navigate("/");
  }, [navigate]);

  useEffect(() => {
    if (!bigMovieMatch) {
      setActiveLayoutId(null);
    }
  }, [bigMovieMatch]);

  const isLoading = nowPlayingLoading && !nowPlayingData;
  const bannerMovie = nowPlayingData?.results[0];

  const allMovies = useMemo(() => {
    const merged = [
      ...(nowPlayingData?.results ?? []),
      ...(topRatedData?.results ?? []),
      ...(upcomingData?.results ?? []),
    ];
    const uniqueById = new Map<number, Movie>();
    merged.forEach((movie) => {
      if (!uniqueById.has(movie.id)) {
        uniqueById.set(movie.id, movie);
      }
    });
    return Array.from(uniqueById.values());
  }, [nowPlayingData, topRatedData, upcomingData]);

  const clickedMovie = bigMovieMatch
    ? allMovies.find(
        (movie) => movie.id === Number(bigMovieMatch.params.movieId)
      )
    : null;

  const coverImagePath =
    clickedMovie?.backdrop_path || clickedMovie?.poster_path || "";

  const bigMovieLayoutId =
    activeLayoutId ??
    (bigMovieMatch ? `movie-${bigMovieMatch.params.movieId}` : undefined);

  return (
    <Wrapper>
      {isLoading ? (
        <Loader>Loading....</Loader>
      ) : (
        <>
          {bannerMovie && (
            <Banner
              onClick={onBannerClick}
              bgphoto={makeImagePath(
                bannerMovie.backdrop_path || bannerMovie.poster_path || ""
              )}
            >
              <Title>{bannerMovie.title}</Title>
              <Overview>{bannerMovie.overview}</Overview>
            </Banner>
          )}
          <MovieSlider
            title="Latest Movies"
            sliderId="nowPlaying"
            data={nowPlayingData}
            hideFirstMovie
            overlapBanner
            onBoxClick={onBoxClicked}
            registerNext={registerNowPlayingNext}
            activeLayoutId={activeLayoutId}
          />
          <MovieSlider
            title="Top Rated Movies"
            sliderId="topRated"
            data={topRatedData}
            onBoxClick={onBoxClicked}
            activeLayoutId={activeLayoutId}
          />
          <MovieSlider
            title="Upcoming Movies"
            sliderId="upcoming"
            data={upcomingData}
            onBoxClick={onBoxClicked}
            activeLayoutId={activeLayoutId}
          />
          <AnimatePresence>
            {bigMovieMatch && clickedMovie ? (
              <>
                <Overlay
                  onClick={onOverlayClick}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                />
                <BigMovie
                  style={{ top: scrollY.get() + 100 }}
                  {...(bigMovieLayoutId ? { layoutId: bigMovieLayoutId } : {})}
                  transition={{
                    type: "spring",
                    damping: 25,
                    stiffness: 200,
                  }}
                >
                  <BigCover
                    style={{
                      backgroundImage: coverImagePath
                        ? `url(${makeImagePath(
                            coverImagePath,
                            "w500"
                          )})`
                        : "linear-gradient(to bottom, #1a1a1a, #0a0a0a)",
                    }}
                  />
                  <BigContent>
                    <BigTitle
                      as={motion.h3}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.3, duration: 0.4 }}
                    >
                      {clickedMovie.title}
                    </BigTitle>
                    <BigMetadata
                      as={motion.div}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ delay: 0.35, duration: 0.4 }}
                    >
                      {clickedMovie.vote_average && (
                        <>
                          <MetadataItem className="rating">
                            ★ {clickedMovie.vote_average.toFixed(1)}
                          </MetadataItem>
                          <Separator>•</Separator>
                        </>
                      )}
                      {clickedMovie.release_date && (
                        <>
                          <MetadataItem className="year">
                            {new Date(clickedMovie.release_date).getFullYear()}
                          </MetadataItem>
                          <Separator>•</Separator>
                        </>
                      )}
                      <MetadataItem>
                        {clickedMovie.adult ? "18+" : "PG-13"}
                      </MetadataItem>
                    </BigMetadata>
                    <BigOverView
                      as={motion.p}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.4, duration: 0.4 }}
                    >
                      {clickedMovie.overview || "No overview available."}
                    </BigOverView>
                  </BigContent>
                </BigMovie>
              </>
            ) : null}
          </AnimatePresence>
        </>
      )}
    </Wrapper>
  );
}

export default Home;
