const rowVariants = {
  hidden: {
    x: typeof window === "undefined" ? 0 : window.outerWidth + 5,
  },
  visible: {
    x: 0,
  },
  exit: {
    x: typeof window === "undefined" ? 0 : -window.outerWidth - 5,
  },
};

const boxVariants: Variants = {
  normal: {
    scale: 1,
    y: 0,
  },
  hover: {
    scale: 1.3,
    y: -50,
    transition: {
      delay: 0.3,
      duration: 0.3,
      type: "tween",
      ease: "easeOut",
    },
  },
};

const infoVariants: Variants = {
  hover: {
    opacity: 1,
    transition: {
      duration: 0.15,
      type: "tween",
    },
  },
};

const offset = 6;

interface ShowSliderProps {
  title: string;
  sliderId: string;
  data?: IGetTvShowsResult;
  hideFirstShow?: boolean;
  overlapBanner?: boolean;
  onBoxClick: ShowClickHandler;
  activeLayoutId?: string | null;
}

function ShowSlider({
  title,
  sliderId,
  data,
  hideFirstShow,
  overlapBanner,
  onBoxClick,
  activeLayoutId,
}: ShowSliderProps) {
  const [index, setIndex] = useState(0);
  const [leaving, setLeaving] = useState(false);

  const shows = data?.results ?? [];
  const showsToShow = hideFirstShow ? shows.slice(1) : shows;
  const totalShows = showsToShow.length;
  const pageCount = Math.max(Math.ceil(totalShows / offset), 1);
  const hasMultiplePages = pageCount > 1;

  useEffect(() => {
    setIndex(0);
    setLeaving(false);
  }, [totalShows]);

  const toggleLeaving = useCallback(() => setLeaving((prev) => !prev), []);

  const handleNext = useCallback(() => {
    if (leaving || !totalShows) return;
    const maxIndex = pageCount - 1;
    const nextIndex = index === maxIndex ? 0 : index + 1;
    if (nextIndex === index) return;
    toggleLeaving();
    setIndex(nextIndex);
  }, [index, leaving, pageCount, toggleLeaving, totalShows]);

  if (!totalShows) {
    return null;
  }

  const chunkStart = offset * index;
  const showsOnPage = showsToShow.slice(chunkStart, chunkStart + offset);

  return (
    <SliderSection $overlap={overlapBanner}>
      <SliderHeader $overlap={overlapBanner}>
        <SliderTitle>{title}</SliderTitle>
        {hasMultiplePages ? (
          <ControlButton
            type="button"
            onClick={handleNext}
            disabled={leaving}
            aria-label={`Show more ${title.toLowerCase()}`}
          >
            Next <span aria-hidden="true">›</span>
          </ControlButton>
        ) : null}
      </SliderHeader>
      <SliderViewport $overlap={overlapBanner}>
        <AnimatePresence initial={false} onExitComplete={toggleLeaving}>
          <Row
            key={`${sliderId}-${index}`}
            variants={rowVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
            transition={{ type: "tween", duration: 1 }}
          >
            {showsOnPage.map((show) => {
              const layoutId = `${sliderId}-${show.id}`;
              const posterPath = show.backdrop_path || show.poster_path || "";
              const backgroundImage = posterPath
                ? makeImagePath(posterPath, "w500")
                : "";
              return (
                <Box
                  key={layoutId}
                  layoutId={layoutId}
                  whileHover="hover"
                  initial="normal"
                  variants={boxVariants}
                  onClick={() => onBoxClick(show, layoutId)}
                  transition={{ type: "tween" }}
                  bgphoto={backgroundImage}
                  $isActive={layoutId === activeLayoutId}
                >
                  <Info variants={infoVariants}>
                    <h4>{show.name}</h4>
                  </Info>
                </Box>
              );
            })}
          </Row>
        </AnimatePresence>
      </SliderViewport>
    </SliderSection>
  );
}

function Tv() {
  const navigate = useNavigate();
  const bigShowMatch = useMatch("/tv/:showId");
  const { scrollY } = useScroll();

  const { data: latestShows, isLoading: latestLoading } =
    useQuery<IGetTvShowsResult>({
      queryKey: ["tv", "latest"],
      queryFn: getLatestShows,
    });
  const { data: airingTodayShows } = useQuery<IGetTvShowsResult>({
    queryKey: ["tv", "airingToday"],
    queryFn: getAiringTodayShows,
  });
  const { data: popularShows } = useQuery<IGetTvShowsResult>({
    queryKey: ["tv", "popular"],
    queryFn: getPopularShows,
  });
  const { data: topRatedShows } = useQuery<IGetTvShowsResult>({
    queryKey: ["tv", "topRated"],
    queryFn: getTopRatedShows,
  });

  const [activeLayoutId, setActiveLayoutId] = useState<string | null>(null);

  const onShowClick = useCallback<ShowClickHandler>(
    (show, layoutId) => {
      setActiveLayoutId(layoutId);
      navigate(`/tv/${show.id}`);
    },
    [navigate]
  );

  const onOverlayClick = useCallback(() => {
    navigate("/tv");
  }, [navigate]);

  useEffect(() => {
    if (!bigShowMatch) {
      setActiveLayoutId(null);
    }
  }, [bigShowMatch]);

  const bannerShow = latestShows?.results[0];

  const allShows = useMemo(() => {
    const merged = [
      ...(latestShows?.results ?? []),
      ...(airingTodayShows?.results ?? []),
      ...(popularShows?.results ?? []),
      ...(topRatedShows?.results ?? []),
    ];
    const uniqueById = new Map<number, TvShow>();
    merged.forEach((show) => {
      if (!uniqueById.has(show.id)) {
        uniqueById.set(show.id, show);
      }
    });
    return Array.from(uniqueById.values());
  }, [latestShows, airingTodayShows, popularShows, topRatedShows]);

  const clickedShow = bigShowMatch
    ? allShows.find((show) => show.id === Number(bigShowMatch.params.showId))
    : null;

  const coverImagePath =
    clickedShow?.backdrop_path || clickedShow?.poster_path || "";

  const bigShowLayoutId =
    activeLayoutId ??
    (bigShowMatch ? `show-${bigShowMatch.params.showId}` : undefined);

  const isLoading = latestLoading && !latestShows;

  return (
    <Wrapper>
      {isLoading ? (
        <Loader>Loading....</Loader>
      ) : (
        <>
          {bannerShow && (
            <Banner
              bgphoto={makeImagePath(
                bannerShow.backdrop_path || bannerShow.poster_path || ""
              )}
              onClick={() => onShowClick(bannerShow, `banner-${bannerShow.id}`)}
            >
              <BannerTitle>{bannerShow.name}</BannerTitle>
              <BannerOverview>{bannerShow.overview}</BannerOverview>
            </Banner>
          )}
          <ShowSlider
            title="Latest Shows"
            sliderId="latest"
            data={latestShows}
            hideFirstShow
            overlapBanner
            onBoxClick={onShowClick}
            activeLayoutId={activeLayoutId}
          />
          <ShowSlider
            title="Airing Today"
            sliderId="airingToday"
            data={airingTodayShows}
            onBoxClick={onShowClick}
            activeLayoutId={activeLayoutId}
          />
          <ShowSlider
            title="Popular"
            sliderId="popular"
            data={popularShows}
            onBoxClick={onShowClick}
            activeLayoutId={activeLayoutId}
          />
          <ShowSlider
            title="Top Rated"
            sliderId="topRated"
            data={topRatedShows}
            onBoxClick={onShowClick}
            activeLayoutId={activeLayoutId}
          />
          <AnimatePresence>
            {bigShowMatch && clickedShow ? (
              <>
                <Overlay
                  onClick={onOverlayClick}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                />
                <BigShow
                  style={{ top: scrollY.get() + 100 }}
                  {...(bigShowLayoutId ? { layoutId: bigShowLayoutId } : {})}
                  transition={{
                    type: "spring",
                    damping: 25,
                    stiffness: 200,
                  }}
                >
                  <BigCover
                    style={{
                      backgroundImage: coverImagePath
                        ? `url(${makeImagePath(coverImagePath, "w500")})`
                        : "linear-gradient(to bottom, #1a1a1a, #0a0a0a)",
                    }}
                  />
                  <BigContent>
                    <BigTitle
                      as={motion.h3}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.3, duration: 0.4 }}
                    >
                      {clickedShow.name}
                    </BigTitle>
                    <BigMetadata
                      as={motion.div}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ delay: 0.35, duration: 0.4 }}
                    >
                      {clickedShow.vote_average && (
                        <>
                          <MetadataItem className="rating">
                            ★ {clickedShow.vote_average.toFixed(1)}
                          </MetadataItem>
                          <Separator>•</Separator>
                        </>
                      )}
                      {clickedShow.first_air_date && (
                        <>
                          <MetadataItem className="year">
                            {new Date(clickedShow.first_air_date).getFullYear()}
                          </MetadataItem>
                          <Separator>•</Separator>
                        </>
                      )}
                      <MetadataItem>TV Series</MetadataItem>
                    </BigMetadata>
                    <BigOverview
                      as={motion.p}
                      initial={{ opacity: 0, y: 20 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ delay: 0.4, duration: 0.4 }}
                    >
                      {clickedShow.overview || "No overview available."}
                    </BigOverview>
                  </BigContent>
                </BigShow>
              </>
            ) : null}
          </AnimatePresence>
        </>
      )}
    </Wrapper>
  );
}

export default Tv;
